CREATE TABLE IF NOT EXISTS public."promotional_video_reactions" (
    "reaction_id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "comment_id" bigint REFERENCES public."promotional_video_comments" ("comment_id") ON DELETE CASCADE,
    "reply_id" bigint REFERENCES public."promotional_video_replies" ("reply_id") ON DELETE CASCADE,
    "user_id" integer NOT NULL REFERENCES public."users" ("user_id") ON DELETE CASCADE,
    "reaction" text NOT NULL CHECK ("reaction" IN ('like', 'love', 'haha', 'wow', 'sad', 'angry')),
    "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (
        ("comment_id" IS NOT NULL AND "reply_id" IS NULL)
        OR ("comment_id" IS NULL AND "reply_id" IS NOT NULL)
    )
);

CREATE UNIQUE INDEX IF NOT EXISTS "promotional_video_reactions_comment_user_key"
    ON public."promotional_video_reactions" ("comment_id", "user_id")
    WHERE "comment_id" IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "promotional_video_reactions_reply_user_key"
    ON public."promotional_video_reactions" ("reply_id", "user_id")
    WHERE "reply_id" IS NOT NULL;

ALTER TABLE public."promotional_video_reactions" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public."promotional_video_reactions" FROM PUBLIC, anon, authenticated;
GRANT ALL ON TABLE public."promotional_video_reactions" TO service_role;
GRANT USAGE, SELECT ON SEQUENCE public."promotional_video_reactions_reaction_id_seq"
    TO service_role;

CREATE OR REPLACE FUNCTION public.get_promotional_video_discussion()
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $function$
    SELECT jsonb_build_object(
        'video_url', (
            SELECT settings."video_url"
              FROM public."promotional_video_settings" AS settings
             WHERE settings."setting_id" = 1
        ),
        'likes_count', (
            SELECT count(*) FROM public."promotional_video_likes"
        ),
        'comments_count', (
            SELECT count(*) FROM public."promotional_video_comments"
        ),
        'liked_by_me', CASE
            WHEN auth.uid() IS NULL THEN false
            ELSE EXISTS (
                SELECT 1
                  FROM public."promotional_video_likes" AS video_like
                  JOIN public."users" AS account ON account."user_id" = video_like."user_id"
                 WHERE account."auth_user_id" = auth.uid()
                   AND account."is_active" = 1
            )
        END,
        'comments', COALESCE((
            SELECT jsonb_agg(
                jsonb_build_object(
                    'comment_id', root_comment."comment_id",
                    'full_name', COALESCE(
                        NULLIF(btrim(root_comment."full_name"), ''),
                        root_comment."username",
                        'User'
                    ),
                    'comment', root_comment."comment",
                    'created_at', root_comment."created_at",
                    'is_mine', root_comment."is_mine",
                    'replies_count', root_comment."replies_count",
                    'reactions', root_comment."reactions",
                    'replies', root_comment."replies"
                )
                ORDER BY root_comment."created_at" DESC, root_comment."comment_id" DESC
            )
              FROM (
                SELECT visible_comment."comment_id",
                       visible_comment."full_name",
                       visible_comment."username",
                       visible_comment."comment",
                       visible_comment."created_at",
                       visible_comment."is_mine",
                       (SELECT count(*)
                          FROM public."promotional_video_replies" AS reply_count
                         WHERE reply_count."comment_id" = visible_comment."comment_id"
                       ) AS "replies_count",
                       COALESCE((
                           SELECT jsonb_agg(
                               jsonb_build_object(
                                   'reaction', comment_reaction."reaction",
                                   'count', comment_reaction."reaction_count",
                                   'reacted_by_me', COALESCE(comment_reaction."reacted_by_me", false)
                               )
                               ORDER BY comment_reaction."reaction"
                           )
                             FROM (
                                SELECT reaction."reaction",
                                       count(*) AS "reaction_count",
                                       bool_or(reaction."user_id" = public.current_app_user_id()) AS "reacted_by_me"
                                  FROM public."promotional_video_reactions" AS reaction
                                 WHERE reaction."comment_id" = visible_comment."comment_id"
                                 GROUP BY reaction."reaction"
                             ) AS comment_reaction
                       ), '[]'::jsonb) AS "reactions",
                       COALESCE((
                           SELECT jsonb_agg(
                               jsonb_build_object(
                                   'reply_id', reply_item."reply_id",
                                   'full_name', COALESCE(
                                       NULLIF(btrim(reply_item."full_name"), ''),
                                       reply_item."username",
                                       'User'
                                   ),
                                   'reply', reply_item."reply",
                                   'created_at', reply_item."created_at",
                                   'is_mine', reply_item."is_mine",
                                   'reactions', reply_item."reactions"
                               )
                               ORDER BY reply_item."created_at", reply_item."reply_id"
                           )
                             FROM (
                                SELECT recent_reply."reply_id",
                                       recent_reply."full_name",
                                       recent_reply."username",
                                       recent_reply."reply",
                                       recent_reply."created_at",
                                       recent_reply."is_mine",
                                       COALESCE((
                                           SELECT jsonb_agg(
                                               jsonb_build_object(
                                                   'reaction', reply_reaction."reaction",
                                                   'count', reply_reaction."reaction_count",
                                                   'reacted_by_me', COALESCE(reply_reaction."reacted_by_me", false)
                                               )
                                               ORDER BY reply_reaction."reaction"
                                           )
                                             FROM (
                                                SELECT reaction."reaction",
                                                       count(*) AS "reaction_count",
                                                       bool_or(reaction."user_id" = public.current_app_user_id()) AS "reacted_by_me"
                                                  FROM public."promotional_video_reactions" AS reaction
                                                 WHERE reaction."reply_id" = recent_reply."reply_id"
                                                 GROUP BY reaction."reaction"
                                             ) AS reply_reaction
                                       ), '[]'::jsonb) AS "reactions"
                                  FROM (
                                    SELECT video_reply."reply_id",
                                           reply_author."full_name",
                                           reply_author."username",
                                           video_reply."reply",
                                           video_reply."created_at",
                                           auth.uid() IS NOT NULL
                                               AND reply_author."auth_user_id" = auth.uid()
                                               AND reply_author."is_active" = 1 AS "is_mine"
                                      FROM public."promotional_video_replies" AS video_reply
                                      JOIN public."users" AS reply_author
                                        ON reply_author."user_id" = video_reply."user_id"
                                     WHERE video_reply."comment_id" = visible_comment."comment_id"
                                     ORDER BY video_reply."created_at" DESC, video_reply."reply_id" DESC
                                     LIMIT 100
                                  ) AS recent_reply
                             ) AS reply_item
                       ), '[]'::jsonb) AS "replies"
                  FROM (
                    SELECT video_comment."comment_id",
                           comment_author."full_name",
                           comment_author."username",
                           video_comment."comment",
                           video_comment."created_at",
                           auth.uid() IS NOT NULL
                               AND comment_author."auth_user_id" = auth.uid()
                               AND comment_author."is_active" = 1 AS "is_mine",
                           row_number() OVER (
                               ORDER BY video_comment."created_at" DESC, video_comment."comment_id" DESC
                           ) AS "list_position"
                      FROM public."promotional_video_comments" AS video_comment
                      JOIN public."users" AS comment_author
                        ON comment_author."user_id" = video_comment."user_id"
                  ) AS visible_comment
                 WHERE visible_comment."list_position" <= 100 OR visible_comment."is_mine"
              ) AS root_comment
        ), '[]'::jsonb)
    );
$function$;

CREATE OR REPLACE FUNCTION public.toggle_promotional_video_reaction(
    p_target_type text,
    p_target_id bigint,
    p_reaction text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE
    app_user_id integer;
    existing_reaction text;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Sign in to react.';
    END IF;
    app_user_id := public.current_app_user_id();
    IF app_user_id IS NULL THEN
        RAISE EXCEPTION 'An active account is required to react.';
    END IF;
    IF p_target_type IS NULL OR p_target_type NOT IN ('comment', 'reply')
       OR p_target_id IS NULL OR p_target_id <= 0
       OR p_reaction IS NULL
       OR p_reaction NOT IN ('like', 'love', 'haha', 'wow', 'sad', 'angry') THEN
        RAISE EXCEPTION 'Choose a valid reaction.';
    END IF;

    IF p_target_type = 'comment' THEN
        PERFORM 1
          FROM public."promotional_video_comments"
         WHERE "comment_id" = p_target_id
         FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Comment not found.';
        END IF;

        SELECT "reaction"
          INTO existing_reaction
          FROM public."promotional_video_reactions"
         WHERE "comment_id" = p_target_id
           AND "user_id" = app_user_id;

        IF existing_reaction = p_reaction THEN
            DELETE FROM public."promotional_video_reactions"
             WHERE "comment_id" = p_target_id
               AND "user_id" = app_user_id;
            RETURN jsonb_build_object('type', 'success', 'active', false);
        ELSIF existing_reaction IS NOT NULL THEN
            UPDATE public."promotional_video_reactions"
               SET "reaction" = p_reaction,
                   "created_at" = CURRENT_TIMESTAMP
             WHERE "comment_id" = p_target_id
               AND "user_id" = app_user_id;
        ELSE
            INSERT INTO public."promotional_video_reactions" ("comment_id", "user_id", "reaction")
            VALUES (p_target_id, app_user_id, p_reaction);
        END IF;
    ELSE
        PERFORM 1
          FROM public."promotional_video_replies"
         WHERE "reply_id" = p_target_id
         FOR UPDATE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Reply not found.';
        END IF;

        SELECT "reaction"
          INTO existing_reaction
          FROM public."promotional_video_reactions"
         WHERE "reply_id" = p_target_id
           AND "user_id" = app_user_id;

        IF existing_reaction = p_reaction THEN
            DELETE FROM public."promotional_video_reactions"
             WHERE "reply_id" = p_target_id
               AND "user_id" = app_user_id;
            RETURN jsonb_build_object('type', 'success', 'active', false);
        ELSIF existing_reaction IS NOT NULL THEN
            UPDATE public."promotional_video_reactions"
               SET "reaction" = p_reaction,
                   "created_at" = CURRENT_TIMESTAMP
             WHERE "reply_id" = p_target_id
               AND "user_id" = app_user_id;
        ELSE
            INSERT INTO public."promotional_video_reactions" ("reply_id", "user_id", "reaction")
            VALUES (p_target_id, app_user_id, p_reaction);
        END IF;
    END IF;

    RETURN jsonb_build_object('type', 'success', 'active', true, 'reaction', p_reaction);
END;
$function$;

REVOKE ALL ON FUNCTION public.toggle_promotional_video_reaction(text, bigint, text)
    FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.toggle_promotional_video_reaction(text, bigint, text)
    TO authenticated;
